WITH flattened AS (SELECT id, customer_id, item.product_id, item.qty, item.price, item.promo FROM (SELECT id, customer_id, EXPLODE_OUTER(items) AS item FROM carts) li) SELECT CASE WHEN price >= 200 THEN 'LARGE' ELSE 'SMALL' END AS price_tier, COUNT(*) AS num_rows, MAX(price) AS max_price, GROUPING(CASE WHEN price >= 200 THEN 'LARGE' ELSE 'SMALL' END) AS grouping_id FROM flattened GROUP BY ROLLUP (CASE WHEN price >= 200 THEN 'LARGE' ELSE 'SMALL' END) HAVING COUNT(*) < 1 ORDER BY num_rows NULLS FIRST;
